/* empty css                                                                                   */import{c as a,o as r,a1 as e}from"./chunks/framework.Hgs72MSy.js";const n=e('<h1 id="ovningsuppgifter" tabindex="-1">Övningsuppgifter <a class="header-anchor" href="#ovningsuppgifter" aria-label="Permalink to &quot;Övningsuppgifter&quot;">​</a></h1><p>I dessa övningar får du möjlighet att utforska viktiga programmeringsbegrepp, såsom:</p><ul><li><span class="a">variabler</span> och <span class="a">datatyper</span>, som hjälper dig att lagra och hantera information i dina program,</li><li>med <span class="a">inmatning</span> och <span class="a">utmatning</span> lär dig att interagera med användaren via sensorer och monitor,</li><li><span class="a">villkorssatser</span> används för att fatta beslut baserat på olika förhållanden,</li><li><span class="a">for-loopar</span> gör det möjligt att upprepa kodblock ett antal gånger,</li><li>med <span class="a">arrays</span> för att lagra flera värden i en och samma variabel,</li><li>och <span class="a">funktioner</span> som gör din kod mer strukturerad och återanvändbar.</li></ul><p>Genom att använda dessa tekniker kan du bygga mer komplexa och dynamiska Arduino-projekt.</p><h2 id="_1-variabler-och-datatyper" tabindex="-1">1. Variabler och Datatyper <a class="header-anchor" href="#_1-variabler-och-datatyper" aria-label="Permalink to &quot;1. Variabler och Datatyper&quot;">​</a></h2><h3 id="ovningar" tabindex="-1">Övningar: <a class="header-anchor" href="#ovningar" aria-label="Permalink to &quot;Övningar:&quot;">​</a></h3><ol><li><p>Skapa en variabel som heter ledPin och sätt dess värde till 13 (använd int som datatyp).</p></li><li><p>Skapa en float-variabel som heter temperature och sätt dess värde till 25.5.</p></li><li><p>Deklarera en boolean-variabel som heter isButtonPressed och sätt den till false.</p></li><li><p>Skapa två heltalsvariabler, a och b, sätt värdena till 5 respektive 10 och beräkna deras summa i en tredje variabel sum.</p></li><li><p>Skapa en konstant LED_PIN och sätt dess värde till 7.</p></li></ol><h2 id="_2-utmatning-och-inmatning" tabindex="-1">2. Utmatning och Inmatning <a class="header-anchor" href="#_2-utmatning-och-inmatning" aria-label="Permalink to &quot;2. Utmatning och Inmatning&quot;">​</a></h2><h3 id="ovningar-1" tabindex="-1">Övningar: <a class="header-anchor" href="#ovningar-1" aria-label="Permalink to &quot;Övningar:&quot;">​</a></h3><ol><li><p>Sätt upp en LED på pin 13 som du kan tända och släcka i koden.</p></li><li><p>Läs ett värde från en knapp ansluten till pin 2.</p></li><li><p>Använd analogRead för att läsa värdet från en potentiometer kopplad till analog pin A0.</p></li><li><p>Använd Serial.print för att skriva &quot;Hello, Arduino!&quot; till Serial Monitor.</p></li></ol><h2 id="_3-villkorssatser" tabindex="-1">3. Villkorssatser <a class="header-anchor" href="#_3-villkorssatser" aria-label="Permalink to &quot;3. Villkorssatser&quot;">​</a></h2><h3 id="ovningar-2" tabindex="-1">Övningar: <a class="header-anchor" href="#ovningar-2" aria-label="Permalink to &quot;Övningar:&quot;">​</a></h3><ol><li><p>Läs in en knapp och skriv ut om den är intryckt eller ej.</p></li><li><p>Läs ett potentiometer-värde och tänd en LED om värdet är över 512.</p></li><li><p>Använd ett villkor för att kontrollera om en variabel temperature är över 30, och skriv ut &quot;Hot!&quot; om så är fallet.</p></li><li><p>Kombinera två villkor för att kolla om både a är större än 5 och b är mindre än 10.</p></li><li><p>Använd else if för att skriva ut olika meddelanden beroende på lightLevel variabelns värde.</p></li></ol><h2 id="_4-for-loopar" tabindex="-1">4. For-loopar <a class="header-anchor" href="#_4-for-loopar" aria-label="Permalink to &quot;4. For-loopar&quot;">​</a></h2><h3 id="ovningar-3" tabindex="-1">Övningar: <a class="header-anchor" href="#ovningar-3" aria-label="Permalink to &quot;Övningar:&quot;">​</a></h3><ol><li><p>Blinka en LED 10 gånger med hjälp av en for-loop.</p></li><li><p>Räkna uppåt från 1 till 5 och skriv ut varje siffra till Serial Monitor.</p></li><li><p>Använd en for-loop för att ändra PWM värdet på en LED från 0 till 255.</p></li><li><p>Skapa en loop som räknar ner från 10 till 0.</p></li><li><p>Läs från en array och skriv ut varje värde till Serial Monitor.</p></li></ol><h2 id="_5-arrays-listor" tabindex="-1">5. Arrays (Listor) <a class="header-anchor" href="#_5-arrays-listor" aria-label="Permalink to &quot;5. Arrays (Listor)&quot;">​</a></h2><h3 id="ovningar-4" tabindex="-1">Övningar: <a class="header-anchor" href="#ovningar-4" aria-label="Permalink to &quot;Övningar:&quot;">​</a></h3><ol><li><p>Skapa en array med heltalen 5, 10, 15, 20.</p></li><li><p>Använd en for-loop för att skriva ut alla värden i en array.</p></li><li><p>Beräkna summan av alla värden i en array.</p></li><li><p>Skapa en array med booleans som indikerar om en LED är på eller av.</p></li><li><p>Ändra värdena i en array med hjälp av en loop.</p></li></ol><h2 id="_6-funktioner" tabindex="-1">6. Funktioner <a class="header-anchor" href="#_6-funktioner" aria-label="Permalink to &quot;6. Funktioner&quot;">​</a></h2><h3 id="ovningar-5" tabindex="-1">Övningar: <a class="header-anchor" href="#ovningar-5" aria-label="Permalink to &quot;Övningar:&quot;">​</a></h3><ol><li><p>Skapa en funktion som tänder en LED ansluten till en specifik pin. Anropa funktionen i loop.</p></li><li><p>Skapa en funktion som räknar ut summan av två tal och returnerar resultatet. Skriv ut summan i loop.</p></li><li><p>Skapa en funktion som blinkar en LED ett antal gånger som du skickar in som argument.</p></li><li><p>Skapa en funktion som kontrollerar om en temperatur är över 30 grader och returnerar true om det är sant, annars false.</p></li><li><p>Skapa en funktion som tar emot ett PWM-värde som parameter och styr ljusstyrkan på en LED baserat på detta värde.</p></li></ol>',22),i=[n],h=JSON.parse('{"title":"Övningsuppgifter","description":"","frontmatter":{"outline":[1,6]},"headers":[],"relativePath":"applied-prog/exercices/tasks.md","filePath":"applied-prog/exercices/tasks.md"}'),t={name:"applied-prog/exercices/tasks.md"},v=Object.assign(t,{setup(l){return(o,s)=>(r(),a("div",null,i))}});export{h as __pageData,v as default};
